from h import *
import json,sys,time
from func_games import rec,R,pts,fin_ok,header_ok
def warna(b):
    ctx,pg=page(b,360,740); g='warna'; p0=pts(pg); play(pg,g); pg.click('#main [data-a=go]'); pg.wait_for_timeout(300); header_ok(pg,g)
    n_all=pg.evaluate("document.querySelectorAll('#wg .wc').length")
    tot=pg.evaluate("B=BBA.DR.length")
    rec(g,'84 gambar tersedia di data',tot==84,tot)
    rec(g,'tombol Gambar Acak terlihat jelas (lebar penuh, oranye)',pg.evaluate("(()=>{const e=document.querySelector('.wrnd'),r=e.getBoundingClientRect();return r.width>250&&r.height>=44&&getComputedStyle(e).backgroundColor!==''})()"))
    rec(g,'kategori TANPA geser samping (tidak ada kontainer overflow-x)',pg.evaluate("![...document.querySelectorAll('.wk *')].some(e=>{const s=getComputedStyle(e);return (s.overflowX==='auto'||s.overflowX==='scroll')&&e.scrollWidth>e.clientWidth+1&&!e.classList.contains('wpal')})"))
    rec(g,'kategori ditutup dulu, dibuka lewat 1 ketukan',pg.evaluate("document.getElementById('wcatp').hidden")==True)
    pg.click('[data-a=wcatp]'); rec(g,'panel kategori terbuka (12 kategori)',pg.locator('.wct').count()==12 and pg.evaluate("!document.getElementById('wcatp').hidden"),pg.locator('.wct').count())
    pg.click('.wct[data-v="Hewan darat"]'); pg.wait_for_timeout(150)
    rec(g,'pilih kategori: daftar terfilter + tombol kategori berwarna aktif + panel menutup',pg.evaluate("document.querySelectorAll('#wg .wc').length")==18 and pg.evaluate("document.querySelector('.wcat').classList.contains('on')") and pg.evaluate("document.getElementById('wcatp').hidden"),pg.evaluate("document.querySelector('.wcat').innerText"))
    pg.click('.wsg[data-v=Semua]'); pg.wait_for_timeout(100)
    pg.fill('#wq','panda'); pg.wait_for_timeout(300); rec(g,'pencarian "panda"',pg.evaluate("document.querySelectorAll('#wg .wc').length")>=1 and 'Panda' in pg.inner_text('#wg'),pg.evaluate("document.querySelectorAll('#wg .wc').length"))
    pg.fill('#wq',''); pg.wait_for_timeout(250)
    hs=pg.evaluate("(()=>{const e=document.querySelector('.wfv'),r=e.getBoundingClientRect();return [Math.round(r.width),Math.round(r.height)]})()")
    rec(g,'favorit = ikon hati kecil (≤36px)',hs[0]<=36 and hs[1]<=36,hs)
    rec(g,'kartu: nama + titik tingkat kecil (tanpa label ⭐ Sedang)','⭐' not in pg.inner_text('#wg .wc') and pg.locator('#wg .wlvl').count()>0)
    pg.click('#wg .wfv'); pg.wait_for_timeout(100); fid=pg.evaluate("P().wn.fav[0]"); rec(g,'ketuk ♡ → tersimpan di profil (P().wn.fav)',bool(fid),fid)
    pg.click('.wsg[data-v="*fav"]'); pg.wait_for_timeout(100); rec(g,'tampilan Favorit menampilkan 1 gambar',pg.evaluate("document.querySelectorAll('#wg .wc').length")==1)
    pg.click('.wsg[data-v="*mine"]'); pg.wait_for_timeout(100); rec(g,'Karyaku kosong → pesan ramah',pg.evaluate("!document.getElementById('wn0').hidden")and 'Belum ada karya' in pg.inner_text('#wn0'))
    pg.click('.wsg[data-v=Semua]'); pg.wait_for_timeout(100)
    pg.click('[data-a=wrand]'); pg.wait_for_timeout(500)
    rec(g,'Gambar Acak membuka kanvas',pg.locator('.cv').count()==1)
    rec(g,'← di header kanvas kembali ke KATALOG (bukan keluar permainan)','katalog' in pg.evaluate("document.querySelector('.gback').getAttribute('aria-label')"))
    rec(g,'palet 24 warna',pg.locator('.wpal .sw').count()==24)
    ns=pg.locator('.cv .f').count(); 
    pg.click('.wpal .sw >> nth=5'); c5=pg.evaluate("G.c"); pg.locator('.cv .f').nth(0).click(); pg.wait_for_timeout(50)
    f0=pg.evaluate("document.querySelector('.cv .f').style.fill"); 
    pg.click('.wpal .sw >> nth=12'); pg.locator('.cv .f').nth(1).click(); pg.wait_for_timeout(50)
    k=pg.evaluate("Object.keys(P().art).length"); rec(g,'mewarnai 2 bagian (tersimpan)',k==2,k)
    pg.click('[data-a=undo]'); k1=pg.evaluate("Object.keys(P().art).length"); pg.click('[data-a=redo]'); k2=pg.evaluate("Object.keys(P().art).length")
    rec(g,'Undo → 1 bagian, Redo → 2 bagian',k1==1 and k2==2,(k1,k2))
    pg.click('.wera'); pg.locator('.cv .f').nth(1).click(); pg.wait_for_timeout(50); k3=pg.evaluate("Object.keys(P().art).length")
    rec(g,'Penghapus menghapus warna bagian',k3==1,k3)
    pg.click('[data-a=wsavec]'); rec(g,'simpan warna favorit',pg.evaluate("P().wn.cf.length")>=0)
    for i in range(ns): pg.click(f'.wpal .sw >> nth={i%24}'); pg.locator('.cv .f').nth(i).click(); pg.wait_for_timeout(15)
    with pg.expect_download(timeout=8000) as dl: pg.click('[data-a=wpng]')
    nm=dl.value.suggested_filename; rec(g,'Simpan PNG mengunduh berkas .png',nm.endswith('.png'),nm)
    pg.click('[data-a=wshare]'); pg.wait_for_timeout(1200); rec(g,'Bagikan tidak error (fallback unduh di desktop)',not pg.errs,pg.errs[:1])
    pg.click('[data-a=cdone]'); pg.wait_for_timeout(500)
    rec(g,'Selesai → poin bertambah',fin_ok(pg) and pts(pg)>p0,f'{p0}->{pts(pg)}')
    # progres tersimpan setelah refresh
    art=pg.evaluate("Object.keys(P().art).length"); pg.reload(); pg.evaluate("document.getElementById('ld')&&document.getElementById('ld').remove()"); pg.wait_for_timeout(300)
    rec(g,'progres warna & favorit bertahan setelah refresh',pg.evaluate("Object.keys(P().art).length")==art and pg.evaluate("P().wn.fav.length")==1,art)
    rec(g,'tanpa error JS',not pg.errs,pg.errs[:1]); ctx.close()
def puzzle(b):
    ctx,pg=page(b,360,740); g='puzzle'; p0=pts(pg); play(pg,g); pg.click('#main [data-a=go]'); pg.wait_for_timeout(250)
    t=pg.inner_text('#main')
    rec(g,'langkah 1: tidak ada Main Puzzle / Beranda / karakter / tingkat','Main Puzzle' not in t and 'Beranda' not in t and pg.locator('.pzt').count()==0 and pg.locator('.pzl').count()==0 and 'Langkah 1/3' in t)
    rec(g,'langkah 1: 9 kategori, grid 2 kolom',pg.locator('.pzc').count()==9 and pg.evaluate("getComputedStyle(document.querySelector('.pzcats')).gridTemplateColumns.split(' ').length")==2)
    rec(g,'langkah 2/3 terkunci di indikator sebelum kategori dipilih',pg.evaluate("[...document.querySelectorAll('.pzstp')].map(b=>b.disabled).join()")=='false,true,true')
    pg.click('[data-a=pzcat][data-v="hewan-air"]'); pg.wait_for_timeout(500)
    rec(g,'pilih kategori → otomatis ke langkah 2 (karakter, 3 kolom di 360px)','Langkah 2/3' in pg.inner_text('#main') and pg.evaluate("getComputedStyle(document.querySelector('.pzg')).gridTemplateColumns.split(' ').length")==3 and 'Main Puzzle' not in pg.inner_text('#main'))
    nchar=pg.locator('.pzt').count(); pg.click('[data-a=pzimg] >> nth=1'); pg.wait_for_timeout(500)
    rec(g,'pilih karakter → otomatis ke langkah 3; 7 tingkat, grid 2 kolom','Langkah 3/3' in pg.inner_text('#main') and pg.locator('.pzl').count()==7 and pg.evaluate("getComputedStyle(document.querySelector('.pzlvs')).gridTemplateColumns.split(' ').length")==2 and 'Main Puzzle' not in pg.inner_text('#main'),nchar)
    # kembali tanpa menghapus pilihan
    pg.click('[data-a=pzstep][data-v="1"]'); pg.wait_for_timeout(200)
    rec(g,'kembali ke langkah 1 → pilihan kategori & karakter TIDAK hilang',pg.evaluate("[...document.querySelectorAll('.pzstp span')].map(e=>e.innerText).join('|')")!='Kategori|Karakter|Tingkat' and pg.locator('.pzc.on').count()==1,pg.evaluate("[...document.querySelectorAll('.pzstp span')].map(e=>e.innerText).join('|')"))
    pg.click('[data-a=pzback]'); rec(g,'← di langkah 1 keluar ke menu permainan (Bermain)',pg.evaluate("V")=='main')
    play(pg,g); pg.click('#main [data-a=go]'); pg.wait_for_timeout(250)
    rec(g,'buka lagi: pilihan sebelumnya masih ada (sesi)',pg.evaluate("sel_ok=document.querySelectorAll('.pzstp.ok').length")>=2)
    pg.click('[data-a=pzstep][data-v="1"]'); pg.wait_for_timeout(200)
    pg.click('[data-a=pzcat][data-v="dinosaurus"]'); pg.wait_for_timeout(450)
    rec(g,'ganti kategori → karakter direset (milik kategori lama), tingkat tetap',pg.locator('.pzt.on').count()==0)
    pg.click('[data-a=pzimg][data-v="dino-biru"]'); pg.wait_for_timeout(450)
    pg.click('[data-a=pzlv][data-v="0"]'); pg.wait_for_timeout(450)
    rec(g,'semua pilihan lengkap → baru muncul Main Puzzle (3/3)','3/3' in pg.inner_text('#main') and pg.locator('.pzgo').count()==1 and 'Beranda' not in pg.inner_text('#main'))
    pg.click('[data-a=pzgo]'); pg.wait_for_timeout(1500)
    rec(g,'papan: kontrol hanya yang dibutuhkan (Petunjuk, Lihat Gambar; tanpa Zoom/Jeda/Suara/Acak untuk 4 keping tanpa timer)',pg.locator('.pzctl .ghost').count()==2 and pg.locator('#main [data-a=snd]').count()==0 and pg.locator('[data-a=pzre]').count()==1,pg.evaluate("[...document.querySelectorAll('.pzctl .ghost')].map(b=>b.innerText).join('|')"))
    pg.click('.pzp2[data-v="0"]'); pg.click('.pzs2[data-v="1"]'); pg.wait_for_timeout(100)
    rec(g,'salah tempat → pesan ramah, keping tetap',pg.locator('.pzp2').count()==4 and 'coba kotak lain' in pg.inner_text('#pzmsg'))
    # seret keping 1 ke kotak 1 (pointer)
    a=pg.locator('.pzp2[data-v="1"]').bounding_box(); c=pg.locator('.pzs2[data-v="1"]').bounding_box()
    pg.mouse.move(a['x']+a['width']/2,a['y']+a['height']/2); pg.mouse.down(); pg.mouse.move(c['x']+c['width']/2,c['y']+c['height']/2,steps=10); pg.mouse.up(); pg.wait_for_timeout(150)
    rec(g,'seret & lepas (drag and drop) menempatkan keping',pg.evaluate("G.pz.ok")==1,pg.evaluate("G.pz.ok"))
    for k in [0,2,3]: pg.click(f'.pzp2[data-v="{k}"]'); pg.click(f'.pzs2[data-v="{k}"]'); pg.wait_for_timeout(60)
    pg.wait_for_timeout(1200)
    rec(g,'selesai → poin/progres tersimpan',fin_ok(pg) and pg.evaluate("P().pz['dino-biru'].includes(0)") and pts(pg)>p0,f'{p0}->{pts(pg)}')
    rec(g,'tombol layar selesai: Berikutnya / Main Lagi / Menu Puzzle',pg.locator('[data-a=pznext]').count()==1 and pg.locator('[data-a=pzre]').count()>=1 and pg.locator('[data-a=pzmenu]').count()==1)
    # tingkat 35 + timer: Jeda & Zoom muncul
    pg.click('[data-a=pzmenu]'); pg.wait_for_timeout(250); pg.click('[data-a=pzstep][data-v="3"]'); pg.wait_for_timeout(200); pg.click('[data-a=pzlv][data-v="6"]'); pg.wait_for_timeout(450)
    pg.check('#pzt'); pg.click('[data-a=pzgo]'); pg.wait_for_timeout(1500)
    rec(g,'35 keping + timer: Zoom dan Jeda tampil, 35 kotak & 35 keping',pg.locator('[data-a=pzzoom]').count()==1 and pg.locator('[data-a=pzpause]').count()==1 and pg.locator('.pzs2').count()==35 and pg.locator('.pzp2').count()==35)
    pg.click('[data-a=pzpause]'); z1=pg.evaluate("G.pz.paused"); pg.click('[data-a=pzpause]'); rec(g,'Jeda/Lanjut',z1==1 and pg.evaluate("G.pz.paused")==0)
    pg.click('[data-a=pzhint]'); pg.wait_for_timeout(100); rec(g,'Petunjuk menyorot kotak',pg.locator('.pzs2.hint').count()==1)
    pg.click('[data-a=pzre]'); pg.wait_for_timeout(1500); rec(g,'🔁 header mengacak ulang puzzle yang sama',pg.locator('.pzp2').count()==35)
    pg.click('.pzh [data-a=pzmenu]'); pg.wait_for_timeout(250); rec(g,'← di papan kembali ke menu puzzle (siap main)',pg.locator('.pzgo').count()==1)
    rec(g,'tanpa error JS',not pg.errs,pg.errs[:1]); ctx.close()
    # HP kecil 320: karakter 2 kolom
    ctx,pg=page(b,320,568); play(pg,g); pg.click('#main [data-a=go]'); pg.click('[data-a=pzcat][data-v="dinosaurus"]'); pg.wait_for_timeout(500)
    rec(g,'HP 320px: grid karakter 2 kolom',pg.evaluate("getComputedStyle(document.querySelector('.pzg')).gridTemplateColumns.split(' ').length")==2); ctx.close()
if __name__=='__main__':
    with sync_playwright() as p:
        b=p.chromium.launch()
        {'warna':warna,'puzzle':puzzle}[sys.argv[1]](b); b.close()
    json.dump(R,open(f'/home/claude/tests/res_{sys.argv[1]}.json','w'),ensure_ascii=False,indent=1)
